/* FORGE – photo batch 4: Farmer's Carry and Dead Bug.
 * Two exercise-position images and one distinct anatomical muscle view per exercise.
 * The movement pictures retain the approved gym-photo style.
 * Only matched exercise names are overridden, all legacy assets remain untouched.
 */
(function(){
 'use strict';
const photoAssets={"Farmer's Carry":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"Dead Bug":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]};

const previousExercise=window.forgeExerciseIllustrations;
const previousCatalog=window.forgePublicExercisePictures;
const safe=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const titles=['Startposition','Endposition','Beanspruchte Muskelgruppen'];
function picture(name){
 const views=photoAssets[name]; if(!views)return '';
 const html=views.map((src,i)=>'<figure class="forge169-photo"><img src="'+src+'" loading="lazy" decoding="async" alt="'+safe(name)+' – '+titles[i]+'"/><figcaption>'+titles[i]+'</figcaption></figure>').join('');
 const note=name==='Dead Bug'?'Gegenüberliegenden Arm und Bein langsam strecken; die Lendenwirbelsäule bleibt stabil.':'Aufrecht gehen, Kurzhanteln sicher greifen und ruhig kontrollierte Schritte setzen.';
 return '<div class="forge169-photo-grid" data-forge169-photo="'+safe(name)+'">'+html+'</div><p class="forge169-photo-note">'+note+' Maßgeblich sind die Technikhinweise unterhalb der Bilder.</p>';
}
window.forgeExerciseIllustrations=function(name){return Object.prototype.hasOwnProperty.call(photoAssets,name)?picture(name):(typeof previousExercise==='function'?previousExercise(name):'');};
window.forgePublicExercisePictures=function(name){return Object.prototype.hasOwnProperty.call(photoAssets,name)?picture(name):(typeof previousCatalog==='function'?previousCatalog(name):'');};
window.forge169BatchInfo={names:Object.keys(photoAssets),picture};
function style(){
 if(document.getElementById('forge169PhotoStyle'))return;
 const tag=document.createElement('style');tag.id='forge169PhotoStyle';tag.textContent=`
 .forge169-photo-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin:10px 0 12px}
 .forge169-photo{margin:0;overflow:hidden;min-width:0;border-radius:11px;background:#0a161d;border:1px solid #4b655c}
 .forge169-photo img{width:100%;height:auto;display:block;aspect-ratio:auto;object-fit:contain}
 .forge169-photo figcaption{padding:7px 5px 8px;text-align:center;font-size:12px;font-weight:700;color:#e1eee7}
 .forge169-photo:last-child{grid-column:1/-1}
 .forge169-photo:last-child img{width:100%;aspect-ratio:auto;object-fit:contain;max-height:320px}
 .forge169-photo-note{font-size:11px!important;color:#adc2b8!important;line-height:1.45!important;margin:4px 0 13px!important}
 .forge-strength-body:has(.forge169-photo-grid)>.forge159-muscles,
 .forge-strength-body:has(.forge169-photo-grid)>.forge-muscle-map{display:none!important}
 @media(min-width:670px){.forge169-photo-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.forge169-photo:last-child{grid-column:auto}.forge169-photo:last-child img{max-height:none}}
 `;document.head.appendChild(tag);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',style,{once:true});else style();
})();